          ..write('waivedBy: $waivedBy, ')
          ..write('waiveReason: $waiveReason, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
